// The Worker entry: OpenNext's handler with one fix on the way out.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- the file only exists after a build
// @ts-ignore -- generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js'

/**
 * OpenNext labels cached pages for a CDN in front of the app:
 * `s-maxage=…, stale-while-revalidate=2592000`. Cloudflare doesn't cache a
 * Worker's responses, so that does nothing at the edge — but Chrome honours
 * stale-while-revalidate and keeps serving client-side navigation data (RSC)
 * from its own cache for up to 30 days. After a deploy that data points at
 * scripts the deploy removed, so navigating breaks until a full reload.
 *
 * Browsers now revalidate every page and its data instead. Responses that set
 * their own browser lifetime (max-age) are left alone.
 */
function forBrowsers(response: Response): Response {
  const cacheControl = response.headers.get('cache-control')
  if (
    !cacheControl ||
    !/s-maxage/i.test(cacheControl) ||
    /(?:^|[\s,])max-age=/i.test(cacheControl)
  )
    return response

  const fixed = new Response(response.body, response)
  fixed.headers.set('cache-control', 'public, max-age=0, must-revalidate')
  return fixed
}

/**
 * OpenNext only sets Cache-Control on optimized images from local files. The
 * remote repo thumbnails come back without it, so browsers re-request (and
 * re-transform) them on every visit. A day keeps updated thumbnails showing
 * up quickly.
 */
function cacheRemoteImages(request: Request, response: Response): Response {
  if (
    response.status !== 200 ||
    response.headers.has('cache-control') ||
    new URL(request.url).pathname !== '/_next/image'
  )
    return response

  const cached = new Response(response.body, response)
  cached.headers.set(
    'cache-control',
    'public, max-age=86400, stale-while-revalidate=604800'
  )
  return cached
}

const worker = {
  async fetch(request: Request, env: unknown, ctx: unknown) {
    // One canonical host (as on Vercel): www → apex, keeping path and query.
    const url = new URL(request.url)
    if (url.hostname === 'www.emreerden.dev') {
      url.hostname = 'emreerden.dev'
      return Response.redirect(url.toString(), 301)
    }

    const response = await handler.fetch(request, env, ctx)
    return cacheRemoteImages(request, forBrowsers(response))
  },
}

export default worker
